public class Question_14{public static void main(String[]x){int[]a={20,25,30,35,40,45,50,55,60,65,70,75};int k=4,s=0;for(int i=0;i<k;i++)s+=a[i];int best=s,start=0;for(int i=k;i<a.length;i++){s+=a[i]-a[i-k];if(s>best){best=s;start=i-k+1;}}System.out.println("Best 4-hour window: "+start+"-"+(start+3));System.out.println("Total parcels: "+best);System.out.println("Average per hour: "+(best/(double)k));}}